/* ============================================
   Sidebery Expand-On-Hover - Sidebery Styles
   ============================================ */

/* Grace-period delay. NOTE: custom properties don't cross document
   boundaries, so userChrome's --sidebar-collapse-delay isn't visible here.
   Define it locally and keep this value matched to userChrome.css. */
#root {
    --sidebar-collapse-delay: .0s;
}

.Tab .fav-icon {
    left: -2px;
}
div.bottom-bar-space {
    transition: height 0.33s cubic-bezier(0.07, 0.95, 0, 1);
}
.Sidebar, .bottom-space {
    transition: background-color 0.5s cubic-bezier(0, 0, 0, 1) !important;
}
#root:not(:hover) {
    --tabs-indent: 0px;
    --tabs-lvl-opacity: 0;
    .Tab .body {
        width: 32px;
        /* hold full width through the grace period, then collapse */
        transition: width 0.33s cubic-bezier(0.07, 0.95, 0, 1) var(--sidebar-collapse-delay);
    }
    #nav_bar {
        opacity: 0;
        /* hold nav bar visible through the grace period, then fade */
        transition: opacity 0.33s cubic-bezier(0.07, 0.95, 0, 1) var(--sidebar-collapse-delay);
    }
}
/* Prevent top row nav bar jitter on expand */
/* (removed the old `transition: opacity 3s` rule — it was dead code,
    fully overridden by this block below) */
#nav_bar {
    transition: opacity 0.33s cubic-bezier(0.07, 0.95, 0, 1); /* instant fade-in on expand (0s delay) */
    will-change: opacity;
    contain: layout style;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    width: var(--sidebar-expanded-width, 380px) !important;
}
/* Lock pinned tabs to a fixed horizontal-wrap layout */
.PinnedTabsBar {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    width: var(--sidebar-expanded-width, 380px) !important;
}
/* Hide the top and bottom shadows on the sidebery panel */
.top-shadow,
.bottom-shadow {
    display: none !important;
}
